content.arguments:
{"description":"查询全部 Run 的媒体状态","command":"set -e
p=$(python3 -c 'import json; print(json.dumps({"run_ids":[x["run_id"] for x in json.load(open("submission.json"))["items"]],"include_parameters":true}))' | ELECTRON_RUN_AS_NODE=1 "$DSH_HARNESS_COMFYUI_NODE_EXECUTABLE" --expose-internals "$DSH_HARNESS_COMFYUI_CLI" --quiet generation resolve-media --stdin); cp "$p" media-status.json; python3 - <<'PY'
import json
for r in json.load(open('media-status.json'))['runs']:
 print(r['run_id'],r.get('status'),r.get('run_error'),[(x['file_path']) for x in r.get('images',[])])
PY"}

